import{_ as r,o,c as a,a4 as n}from"./chunks/framework.DsCjAhHD.js";const c=JSON.parse('{"title":"分级规则说明","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"guide/tier-system.md","filePath":"guide/tier-system.md","lastUpdated":null}'),l={name:"guide/tier-system.md"};function s(i,t,e,d,g,h){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="分级规则说明" tabindex="-1">分级规则说明 <a class="header-anchor" href="#分级规则说明" aria-label="Permalink to &quot;分级规则说明&quot;">​</a></h1><p>本站排行榜采用 <strong>同职业内名次制</strong>：数组顺序即名次，第一名在最上，类似 CPU 性能排行榜的直观排名。</p><h2 id="档位定义" tabindex="-1">档位定义 <a class="header-anchor" href="#档位定义" aria-label="Permalink to &quot;档位定义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>档位</th><th>颜色</th><th>含义</th></tr></thead><tbody><tr><td><strong>T0</strong></td><td>红色</td><td>断层超模，版本答案，同职业内碾压级优势</td></tr><tr><td><strong>T0.5</strong></td><td>橙色</td><td>顶级强力，上限极高，仅略逊于 T0，熟练后差距极小</td></tr><tr><td><strong>T1</strong></td><td>黄色</td><td>主流强势，综合性能优秀，适配绝大多数场景</td></tr><tr><td><strong>T2</strong></td><td>蓝色</td><td>中规中矩，能用但有明显短板，仅特定场景可用</td></tr><tr><td><strong>T3</strong></td><td>灰色</td><td>玩具/过渡级，性能落后，仅新手过渡或娱乐使用</td></tr></tbody></table><h2 id="评价维度" tabindex="-1">评价维度 <a class="header-anchor" href="#评价维度" aria-label="Permalink to &quot;评价维度&quot;">​</a></h2><h3 id="pvp-维度" tabindex="-1">PVP 维度 <a class="header-anchor" href="#pvp-维度" aria-label="Permalink to &quot;PVP 维度&quot;">​</a></h3><ul><li><strong>伤害</strong>：单发/秒伤、暴击线</li><li><strong>射速/攻速</strong>：DPS 上限</li><li><strong>弹道/精准度</strong>：命中稳定性</li><li><strong>载弹量/换弹速度</strong>：持续作战能力</li><li><strong>特殊机制</strong>：减速、灼烧、治疗、隐身加成等</li><li><strong>容错率</strong>：失误后的挽回空间</li><li><strong>上下限差距</strong>：新手和熟练玩家的表现差异</li></ul><h3 id="pve-维度" tabindex="-1">PVE 维度 <a class="header-anchor" href="#pve-维度" aria-label="Permalink to &quot;PVE 维度&quot;">​</a></h3><ul><li><strong>清怪效率</strong>：AOE 能力、范围伤害</li><li><strong>BOSS 输出</strong>：单体 DPS</li><li><strong>生存加成</strong>：护盾、回血、减伤</li><li><strong>技能联动</strong>：与职业技能的协同效果</li><li><strong>刷钱速度</strong>：金币掉落加成</li><li><strong>专属被动</strong>：PVE 词条效果</li></ul><h2 id="重要原则" tabindex="-1">重要原则 <a class="header-anchor" href="#重要原则" aria-label="Permalink to &quot;重要原则&quot;">​</a></h2><ol><li><strong>同职业内排名</strong>：排行榜只在同一职业内部比较，跨职业不直接对比。</li><li><strong>PVP / PVE 独立</strong>：两把武器分别在 PVP 和 PVE 排行榜中排名，不混排。</li><li><strong>版本绑定</strong>：所有排名都标注版本号，过期排名仅供参考。</li><li><strong>主观成分</strong>：排行榜结合面板数据 + 社区实战共识，存在一定主观判断。</li></ol><h2 id="颜色标识" tabindex="-1">颜色标识 <a class="header-anchor" href="#颜色标识" aria-label="Permalink to &quot;颜色标识&quot;">​</a></h2><ul><li>🔴 <strong>T0</strong>：断层级</li><li>🟠 <strong>T0.5</strong>：顶级</li><li>🟡 <strong>T1</strong>：强势</li><li>🔵 <strong>T2</strong>：一般</li><li>⚪ <strong>T3</strong>：过渡</li></ul>',13)])])}const P=r(l,[["render",s]]);export{c as __pageData,P as default};
